                if x.opcode then opcodes[x.opcode]=(opcodes[x.opcode] or 1)*(1-math.min(x.p,1)) end
            end
        elseif met(x.when) then
            local left=opcodes[x.e.opcode] or 1
            local node=x.node
            while node do
                left=left*(nodes[node] or 1)
                node=c.nodes[node].parent
            end
