        for _,f in ipairs(c.conditions) do
            if type(f)=='table' and f.row~=nil then rows[M.conditionKey(f)]=f end
        end
    end
    if type(c)=='table' and type(c.weapons)=='table' then
        for _,w in ipairs(c.weapons) do M.rows(w.strike,rows) end
    end
    return rows
end

return M
end
