M.COVERS={[109]='hold',[175]='hold',[185]='hold',[5]='charm',[241]='charm',[128]='confusion',
    [24]='panic',[39]='sleep',[217]='sleep',[45]='stun',[210]='stun',[76]='feeblemind',[13]='death',
    [55]='death',[134]='petrify',[38]='silence',[40]='slow'}
