        thac0=(number(cre.thac0) and cre.thac0 or 20)-hit,apr=math.max(defence.attacks(cre.apr),0),
        damage=math.max(damage,0),magical=magical,ranged=ranged,fighter=fighter,level=cre.level,
        gender=cre.gender,ea=cre.ea}
