            local level=number(o.level) and o.level or 9
            local k={-level,ORDER[o.kind=='see' and 'see' or o.center] or 0}
            local better=chosen==nil
            if not better then
                for i=1,#k do
                    if k[i]~=chosenKey[i] then better=k[i]>chosenKey[i];break end
                end
