                g.EEex_Area_ForAllOfTypeStringInRange(area,object.m_pos.x,object.m_pos.y,'[ANYONE]',M.sightRange,
                    function(other) if other~=nil and other.m_id==self.id then found=true end end,1,0,terrain)
